const rule=rules[order];
const saved=JSON.parse(await readFile(new URL('../research/charge-frost-debug-snapshot.json',import.meta.url),'utf8'));
const scratch=await mkdtemp(tmpdir()+'/frost-integral-');
await cp(new URL('../tests/engine/build/',import.meta.url),scratch,{recursive:true});
await writeFile(scratch+'/package.json','{"type":"module"}');
const charge=await readFile(scratch+'/charge.js','utf8');
const needle="const h = this.properties.prop('H', 'P', p, 'S', up.entropyJkgK), rho = this.properties.prop('D', 'P', p, 'S', up.entropyJkgK);";
if(!charge.includes(needle))throw Error('Compiled flux needle absent');
const replacement=`const rho=this.properties.prop('D','P',p,'S',up.entropyJkgK);
const rules={4:${JSON.stringify(rules[4])},8:${JSON.stringify(rules[8])}};
let evaluations=0;
const integrate=(a,b,n)=>{const mid=(a+b)/2,half=(b-a)/2,r=rules[n];return half*r.nodes.reduce((sum,node,i)=>{if(++evaluations>8192)throw new DomainError('Isentropic integral evaluation budget');return sum+r.weights[i]/this.properties.prop('D','P',mid+half*node,'S',up.entropyJkgK)},0)};
const q4=integrate(p,up.pPa,4),q8=integrate(p,up.pPa,8);
const ideal=coefficient*area*rho*Math.sqrt(2*q8);
const drop=up.pPa-p,m=corrected(rho*Math.sqrt(2*q8),drop);
const beta=2*drop*m/ideal**2/(resistance+2*drop*m/ideal**2);
const budget=Math.min(1e-8+1e-9*Math.abs(q8),2*q8*4e-11/Math.max(m*beta,1e-30));
const refine=(a,b,coarse,fine,tolerance,depth)=>{if(Math.abs(coarse-fine)<=tolerance)return fine;if(depth>=16)throw new DomainError('Isentropic integral unresolved error '+JSON.stringify({a,b,coarse,fine,tolerance,width:b-a,difference:Math.abs(coarse-fine)}));const mid=(a+b)/2;return refine(a,mid,integrate(a,mid,4),integrate(a,mid,8),tolerance/2,depth+1)+refine(mid,b,integrate(mid,b,4),integrate(mid,b,8),tolerance/2,depth+1)};
const dh=refine(p,up.pPa,q4,q8,budget,0);
this.quadStats??={fluxCalls:0,densityCalls:0,maxDensityCalls:0};this.quadStats.fluxCalls++;this.quadStats.densityCalls+=evaluations;this.quadStats.maxDensityCalls=Math.max(this.quadStats.maxDensityCalls,evaluations);`;
let revised=charge.replace(needle,replacement).replace('2 * (up.hJkg - h)','2 * dh');
revised=revised.replace(/if \(delta \/ up\.pPa < 1e-6\)\s*return corrected\(Math\.sqrt\(2 \* up\.densityKgm3 \* delta\), delta\);/,'');
if(revised.includes('delta / up.pPa < 1e-6'))throw Error('Failed asymptote removal');
await writeFile(scratch+'/charge.js',revised);
const {ChargeCircuit}=await import(pathToFileURL(scratch+'/charge.js'));
const props=new Properties(await factory()),g=saved.config.inventory.geometry;
const circuit=new ChargeCircuit(props,g,{massKg:saved.config.inventory.initialMassKg,fluidTemperatureC:saved.config.inventory.initialFluidTemperatureC});
const boundary={orientation:saved.fluid.orientation,compressorSpeedRps:saved.output.diagnostics.speedRps,enabledRoomIds:g.rooms.map(r=>r.id),outdoorMetalC:saved.output.outdoor.metalTemperatureC,indoorMetalCById:Object.fromEntries(saved.output.rooms.map(r=>[r.id,r.metalTemperatureC]))};
const start=performance.now();let result;
try{const candidate=process.argv.includes('--representative')?null:circuit.prepareSingle(dt,boundary,saved.fluid);result={dt,order,threshold,accepted:true,wallSeconds:(performance.now()-start)/1000,candidate,quadStats:circuit.quadStats};}
catch(e){result={dt,order,threshold,accepted:false,wallSeconds:(performance.now()-start)/1000,error:String(e)}}
const representative=[];
for(const cell of [saved.fluid.cells[0],saved.fluid.cells[7],saved.fluid.cells[8]])for(const span of [1e-12,1e-9,1e-6,.001,.01,.1,.4,.6]){
 try{const flow=circuit.nozzle(cell.state,cell.state.pPa*(1-span),g.accumulatorInletAreaM2,.65,.1);representative.push({id:cell.id,span,flow,finite:flow>=0&&Number.isFinite(flow)});}catch(e){representative.push({id:cell.id,span,error:String(e)});}
}
result.representative=representative;result.totalWallSeconds=(performance.now()-start)/1000;
await writeFile(new URL(`../research/frost-adaptive-corrected-budget-${dt}.json`,import.meta.url),JSON.stringify(result,null,2)+'\n');
console.log({accepted:result.accepted,wallSeconds:result.wallSeconds,error:result.error,candidateKeys:result.candidate&&Object.keys(result.candidate)});
props.dispose();await rm(scratch,{recursive:true});

